import{_ as s,o as a,c as e,a3 as i}from"./chunks/framework.BTt0kA_k.js";const k=JSON.parse('{"title":"检查与测试","description":"","frontmatter":{},"headers":[],"relativePath":"developer/checks-and-tests.md","filePath":"developer/checks-and-tests.md"}'),d={name:"developer/checks-and-tests.md"};function n(h,t,p,o,c,l){return a(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="检查与测试" tabindex="-1">检查与测试 <a class="header-anchor" href="#检查与测试" aria-label="Permalink to &quot;检查与测试&quot;">​</a></h1><h2 id="按修改范围选择检查" tabindex="-1">按修改范围选择检查 <a class="header-anchor" href="#按修改范围选择检查" aria-label="Permalink to &quot;按修改范围选择检查&quot;">​</a></h2><p>以下命令在仓库根目录执行。先检查受影响部分，再根据变更范围补充相关检查。</p><table tabindex="0"><thead><tr><th>修改范围</th><th>命令</th></tr></thead><tbody><tr><td>前端类型</td><td><code>pnpm typecheck</code></td></tr><tr><td>前端格式与 Lint</td><td><code>pnpm --dir frontend format:check</code>、<code>pnpm lint:frontend</code></td></tr><tr><td>Vue 规则与组件行为</td><td><code>pnpm test:frontend</code></td></tr><tr><td>Rust 格式与 Lint</td><td><code>pnpm format:backend:check</code>、<code>pnpm lint:backend</code></td></tr><tr><td>Rust 规则与模块协作</td><td><code>pnpm test:backend</code></td></tr><tr><td>仓库启动、环境与打包脚本</td><td><code>pnpm lint:scripts</code>、<code>pnpm test:desktop-scripts</code></td></tr><tr><td>前端导航与主题等浏览器流程</td><td><code>pnpm test:e2e</code></td></tr></tbody></table><p><code>pnpm check:all</code> 顺序执行架构、SDK、格式、Lint、类型和测试检查，不执行生产构建。生产打包按<a href="./build-and-environments.html">构建说明</a>在需要验证安装包时单独进行。</p><p>端到端测试配置指定 <code>channel: &#39;chrome&#39;</code>，需要 Google Chrome。已有 Chrome 可直接运行；缺少时安装对应浏览器：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chrome</span></span></code></pre></div><p>浏览器测试使用模拟接口，原生托盘、通知、窗口和真实请求仍需桌面验证。</p><p>每个命令的执行范围、自动修复副作用、测试筛选示例和报告入口见<a href="./commands.html#检查与自动修复">开发命令参考</a>。</p><h2 id="架构与-sdk" tabindex="-1">架构与 SDK <a class="header-anchor" href="#架构与-sdk" aria-label="Permalink to &quot;架构与 SDK&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:architecture</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:sdk</span></span></code></pre></div><p>前者检查宿主产品模块与公共库依赖边界；后者检查 SDK API，并运行独立 SDK 消费者测试。修改公共接口、Cargo 依赖或源码模块路径时，应覆盖这两项。</p><h2 id="测试放在哪里" tabindex="-1">测试放在哪里 <a class="header-anchor" href="#测试放在哪里" aria-label="Permalink to &quot;测试放在哪里&quot;">​</a></h2><p>前端与 Rust 分别在 <code>frontend/tests/</code>、<code>backend/tests/</code> 使用同一分类：</p><table tabindex="0"><thead><tr><th>子目录</th><th>内容</th></tr></thead><tbody><tr><td><code>unit/</code></td><td>单条规则或独立模块</td></tr><tr><td><code>integration/</code></td><td>多模块协作与完整流程</td></tr><tr><td><code>support/</code></td><td>测试夹具、替身和共享辅助函数</td></tr></tbody></table><p>按测试行为命名文件，如 <code>request_parameters.rs</code>、<code>concurrency.rs</code>。Rust 的 <code>mod.rs</code> 用于组装测试套件。</p><p>Rust 模块私有行为仍通过所属模块挂载测试文件；<code>backend/src/</code> 只保留必要的 <code>#[cfg(test)]</code> 与 <code>#[path = &quot;...&quot;]</code> 声明。不要为迁移测试而扩大生产 API 的可见性。</p><h2 id="修改-antdv-next-组件" tabindex="-1">修改 antdv-next 组件 <a class="header-anchor" href="#修改-antdv-next-组件" aria-label="Permalink to &quot;修改 antdv-next 组件&quot;">​</a></h2><p>项目要求先通过本地工具查询 API 和示例，再修改组件。例如使用 Button 时：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.agents/bin/antdv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Button</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.agents/bin/antdv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Button</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> basic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><p>改动后对实际修改目录执行检查，例如：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.agents/bin/antdv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend/src/views/config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><p>使用项目内包装器，完整工作流以仓库 <code>AGENTS.md</code> 和 <code>.agents/skills/antdv/SKILL.md</code> 为准。</p>`,23)])])}const F=s(d,[["render",n]]);export{k as __pageData,F as default};
